-- Mandate-summary tile translations (ES/DE/FR) for the remaining 25 countries.

UPDATE deep_dive_page_translations SET mandate_summary = 'Sigue sin existir un mandato general de facturación electrónica B2B en Australia — la adopción de la red Peppol sigue siendo voluntaria para las empresas privadas. El único requisito vinculante recae sobre el propio gobierno federal: los organismos de la Commonwealth deben poder recibir facturas electrónicas Peppol desde julio de 2022, con objetivos de cumplimiento que aumentan hasta 2026.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Australia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Es gibt in Australien nach wie vor kein allgemeines B2B-E-Invoicing-Mandat — die Nutzung des Peppol-Netzwerks bleibt für private Unternehmen freiwillig. Die einzige verbindliche Anforderung betrifft die Bundesregierung selbst: Commonwealth-Behörden müssen seit Juli 2022 Peppol-E-Rechnungen empfangen können, wobei die Compliance-Ziele bis 2026 weiter steigen.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Australia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Il n''existe toujours aucun mandat général de facturation électronique B2B en Australie — l''adoption du réseau Peppol reste volontaire pour les entreprises privées. La seule exigence contraignante concerne le gouvernement fédéral lui-même : les agences du Commonwealth doivent pouvoir recevoir des factures électroniques Peppol depuis juillet 2022, avec des objectifs de conformité qui s''intensifient jusqu''en 2026.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Australia');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de facturación electrónica B2B de Bélgica está plenamente en vigor: desde el 1 de enero de 2026, las empresas registradas a efectos del IVA deben intercambiar facturas en formato Peppol estructurado. Sigue a años de facturación electrónica B2G a través de la plataforma Mercurius, y se espera que una capa de reporte casi en tiempo real le siga en 2028.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Belgium');
UPDATE deep_dive_page_translations SET mandate_summary = 'Belgiens B2B-E-Invoicing-Mandat ist vollständig in Kraft: Seit dem 1. Januar 2026 müssen umsatzsteuerlich registrierte Unternehmen Rechnungen im strukturierten Peppol-Format austauschen. Dem gehen Jahre des B2G-E-Invoicing über die Mercurius-Plattform voraus, und eine nahezu Echtzeit-Meldeebene soll 2028 folgen.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Belgium');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat belge de facturation électronique B2B est pleinement en vigueur : depuis le 1er janvier 2026, les entreprises immatriculées à la TVA doivent échanger des factures au format Peppol structuré. Cela fait suite à des années de facturation électronique B2G via la plateforme Mercurius, une couche de déclaration quasi en temps réel devant suivre en 2028.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Belgium');
UPDATE deep_dive_page_translations SET mandate_summary = 'Brasil no tiene un único mandato de facturación electrónica — tiene varios, organizados por tipo de transacción y nivel de gobierno, la mayoría vigentes desde hace años. El desarrollo actual es una gran reforma tributaria sobre el consumo (CBS/IBS) que se está incorporando gradualmente a esa infraestructura ya madura, no un nuevo requisito de facturación.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Brazil');
UPDATE deep_dive_page_translations SET mandate_summary = 'Brasilien hat kein einzelnes E-Invoicing-Mandat — es hat mehrere, geschichtet nach Transaktionsart und Regierungsebene, die meisten davon seit Jahren in Kraft. Die aktuelle Entwicklung ist eine große Verbrauchsteuerreform (CBS/IBS), die schrittweise in diese ausgereifte Infrastruktur eingebettet wird, keine neue Rechnungsanforderung.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Brazil');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le Brésil n''a pas un mandat unique de facturation électronique — il en a plusieurs, superposés par type de transaction et niveau d''administration, la plupart en vigueur depuis des années. Le développement actuel est une réforme majeure de la fiscalité sur la consommation (CBS/IBS) intégrée progressivement à cette infrastructure déjà mature, et non une nouvelle exigence de facturation.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Brazil');
UPDATE deep_dive_page_translations SET mandate_summary = 'El modelo de compensación de Chile es obligatorio para todas las empresas desde 2018, lo que lo convierte en uno de los regímenes de facturación electrónica más antiguos de América Latina. La actividad actual es incremental — extender el mismo enfoque de compensación a las boletas al consumidor (boleta electrónica) en lugar de introducir algo nuevo.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Chile');
UPDATE deep_dive_page_translations SET mandate_summary = 'Chiles Clearing-Modell ist seit 2018 für alle Unternehmen verpflichtend und damit eines der am längsten laufenden E-Invoicing-Regime Lateinamerikas. Die aktuelle Entwicklung ist schrittweise — der gleiche Clearing-Ansatz wird auf Verbraucherquittungen (boleta electrónica) ausgeweitet, statt etwas Neues einzuführen.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Chile');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le modèle de contrôle du Chili est obligatoire pour toutes les entreprises depuis 2018, ce qui en fait l''un des régimes de facturation électronique les plus anciens d''Amérique latine. L''activité actuelle est incrémentale — étendre la même approche de contrôle aux reçus à la consommation (boleta electrónica) plutôt que d''introduire quelque chose de nouveau.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Chile');
UPDATE deep_dive_page_translations SET mandate_summary = 'El sistema chino de e-fapiao totalmente digitalizado es obligatorio en todo el país desde diciembre de 2024, el punto final de una implementación gradual y cuidadosamente pilotada durante una década. Cada factura se compensa a través del Golden Tax System antes de ser legalmente válida — existen copias legibles para humanos, pero el XML es el documento legal real.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'China');
UPDATE deep_dive_page_translations SET mandate_summary = 'Chinas vollständig digitalisiertes E-Fapiao-System ist seit Dezember 2024 landesweit verpflichtend — der Endpunkt einer jahrzehntelangen, sorgfältig pilotierten Einführung. Jede Rechnung wird über das Golden-Tax-System freigegeben, bevor sie rechtsgültig ist — menschenlesbare Kopien existieren, aber das XML ist das eigentliche Rechtsdokument.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'China');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le système chinois d''e-fapiao entièrement numérisé est obligatoire dans tout le pays depuis décembre 2024, aboutissement d''un déploiement mené pendant une décennie avec des pilotes soigneusement menés. Chaque facture est contrôlée via le Golden Tax System avant d''être juridiquement valide — des copies lisibles par l''humain existent, mais le XML est le document juridique réel.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'China');
UPDATE deep_dive_page_translations SET mandate_summary = 'La reforma Fiskalizacija 2.0 de Croacia hizo obligatoria la facturación electrónica estructurada y el reporte electrónico para las empresas registradas a efectos del IVA a partir del 1 de enero de 2026, sobre la base de un sistema B2G que funciona desde 2019. Las entidades no registradas a efectos del IVA y los organismos públicos se incorporan al mandato en 2027.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Croatia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Kroatiens Reform Fiskalizacija 2.0 machte strukturiertes E-Invoicing und E-Reporting für umsatzsteuerlich registrierte Unternehmen ab dem 1. Januar 2026 verpflichtend, aufbauend auf einem B2G-System, das bereits seit 2019 läuft. Nicht umsatzsteuerlich registrierte Einrichtungen und öffentliche Stellen treten dem Mandat 2027 bei.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Croatia');
UPDATE deep_dive_page_translations SET mandate_summary = 'La réforme Fiskalizacija 2.0 de la Croatie a rendu obligatoires la facturation électronique structurée et la déclaration électronique pour les entreprises immatriculées à la TVA à partir du 1er janvier 2026, en s''appuyant sur un système B2G en place depuis 2019. Les entités non immatriculées à la TVA et les organismes publics rejoignent le mandat en 2027.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Croatia');
UPDATE deep_dive_page_translations SET mandate_summary = 'La Ley de Contabilidad de Dinamarca es un mandato de capacidad, no un mandato de transmisión: las empresas deben poder emitir y recibir facturas electrónicas, pero no están obligadas a usar esa capacidad en cada transacción. Ya está en vigor para empresas medianas y grandes, extendiéndose a empresas más pequeñas hasta 2026, en el contexto de un formato nacional en evolución que pasa de OIOUBL a NemHandel BIS.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Denmark');
UPDATE deep_dive_page_translations SET mandate_summary = 'Dänemarks Buchführungsgesetz ist ein Fähigkeitsmandat, kein Übertragungsmandat — Unternehmen müssen in der Lage sein, E-Rechnungen auszustellen und zu empfangen, sind aber nicht verpflichtet, diese Fähigkeit bei jeder Transaktion zu nutzen. Es gilt bereits für mittlere und große Unternehmen und wird bis 2026 auf kleinere Unternehmen ausgeweitet, vor dem Hintergrund eines sich wandelnden nationalen Formats von OIOUBL zu NemHandel BIS.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Denmark');
UPDATE deep_dive_page_translations SET mandate_summary = 'La loi danoise sur la comptabilité est un mandat de capacité, pas un mandat de transmission — les entreprises doivent être en mesure d''émettre et de recevoir des factures électroniques, sans être tenues d''utiliser cette capacité pour chaque transaction. Elle est déjà en vigueur pour les moyennes et grandes entreprises, s''étendant aux plus petites jusqu''en 2026, dans un contexte de format national en évolution passant d''OIOUBL à NemHandel BIS.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Denmark');
UPDATE deep_dive_page_translations SET mandate_summary = 'ViDA en sí mismo no crea un mandato doméstico de facturación electrónica en ningún Estado miembro — es un marco a nivel de la UE que se implementa por fases hasta 2035, superpuesto al mandato que ya aplique cada país. Las partes que ya están realmente en vigor son limitadas: los Estados miembros pueden introducir libremente sus propios mandatos domésticos, y un plazo de transposición del Registro Único de IVA vence a finales de 2026.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'European Union');
UPDATE deep_dive_page_translations SET mandate_summary = 'ViDA schafft an sich in keinem Mitgliedstaat ein inländisches E-Invoicing-Mandat — es ist ein EU-weiter Rahmen, der bis 2035 in Phasen eingeführt wird, aufgesetzt auf das Mandat, das jedes Land bereits betreibt. Die Teile, die bereits tatsächlich in Kraft sind, sind begrenzt: Mitgliedstaaten können frei eigene inländische Mandate einführen, und eine Umsetzungsfrist zur einheitlichen USt-Registrierung endet Ende 2026.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'European Union');
UPDATE deep_dive_page_translations SET mandate_summary = 'ViDA ne crée pas en soi un mandat domestique de facturation électronique dans un État membre — c''est un cadre à l''échelle de l''UE se déployant par phases jusqu''en 2035, superposé au mandat déjà en vigueur dans chaque pays. Les éléments réellement déjà en vigueur sont limités : les États membres peuvent introduire librement leurs propres mandats domestiques, et une échéance de transposition de l''immatriculation unique à la TVA arrive fin 2026.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'European Union');
UPDATE deep_dive_page_translations SET mandate_summary = 'Finlandia no tiene ningún mandato doméstico de facturación electrónica B2B — una de las pocas excepciones en este tracker — pero la adopción ya es casi universal en la práctica, impulsada por décadas de uso voluntario. El único requisito vinculante es el B2G: la facturación del sector público es obligatoria desde 2020.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Finland');
UPDATE deep_dive_page_translations SET mandate_summary = 'Finnland hat überhaupt kein inländisches B2B-E-Invoicing-Mandat — eines der wenigen Länder in diesem Tracker in dieser Lage — aber die Nutzung ist in der Praxis bereits nahezu universell, getragen von jahrzehntelanger freiwilliger Anwendung. Die einzige verbindliche Anforderung ist B2G: Die Rechnungsstellung im öffentlichen Sektor ist seit 2020 verpflichtend.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Finland');
UPDATE deep_dive_page_translations SET mandate_summary = 'La Finlande n''a aucun mandat domestique de facturation électronique B2B — l''un des rares pays de ce tracker dans cette situation — mais l''adoption est déjà quasi universelle en pratique, portée par des décennies d''usage volontaire. La seule exigence contraignante est le B2G : la facturation du secteur public est obligatoire depuis 2020.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Finland');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de facturación electrónica B2G de Francia lleva años en vigor, pero la reforma B2B, mucho más amplia, todavía se está implementando por fases: las grandes y medianas empresas deben poder recibir facturas estructuradas desde septiembre de 2026, y el mandato de emisión completo llega a todas las empresas un año después. Una obligación de e-reporting independiente funciona en paralelo para las transacciones fuera del alcance de la facturación electrónica.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'France');
UPDATE deep_dive_page_translations SET mandate_summary = 'Frankreichs B2G-E-Invoicing-Mandat ist seit Jahren in Kraft, aber die weitaus größere B2B-Reform wird noch schrittweise eingeführt: Große und mittlere Unternehmen müssen ab September 2026 strukturierte Rechnungen empfangen können, das vollständige Ausstellungsmandat erreicht ein Jahr später alle Unternehmen. Eine separate E-Reporting-Pflicht läuft parallel für Transaktionen außerhalb des Anwendungsbereichs von E-Invoicing.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'France');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat B2G de facturation électronique de la France est en vigueur depuis des années, mais la réforme B2B, bien plus vaste, est encore en cours de déploiement par phases : les grandes et moyennes entreprises doivent pouvoir recevoir des factures structurées à partir de septembre 2026, le mandat d''émission complet atteignant toutes les entreprises un an plus tard. Une obligation distincte d''e-reporting fonctionne en parallèle pour les transactions hors du champ de la facturation électronique.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'France');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de Alemania llega en etapas cuidadosas: la recepción de facturas estructuradas se volvió obligatoria para todas las empresas a principios de 2025, pero el requisito de emisión no alcanza a las empresas más pequeñas hasta 2028. No hay autoridad de compensación ni obligación de reporte doméstico asociada — Alemania se mantiene totalmente descentralizada en todo momento.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Germany');
UPDATE deep_dive_page_translations SET mandate_summary = 'Deutschlands Mandat kommt in sorgfältig abgestuften Schritten: Der Empfang strukturierter Rechnungen wurde Anfang 2025 für alle Unternehmen verpflichtend, aber die Ausstellungspflicht erreicht kleinere Unternehmen erst 2028. Es gibt keine Freigabebehörde und keine damit verbundene inländische Meldepflicht — Deutschland bleibt durchgehend vollständig dezentral.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Germany');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat allemand arrive par étapes prudentes : la réception de factures structurées est devenue obligatoire pour toutes les entreprises début 2025, mais l''exigence d''émission n''atteint les plus petites entreprises qu''en 2028. Il n''existe aucune autorité de contrôle ni obligation de déclaration domestique associée — l''Allemagne reste entièrement décentralisée tout du long.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Germany');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de facturación electrónica GST de la India se ha implementado reduciendo progresivamente el umbral de facturación en lugar de mediante un único día de entrada en vigor — ahora está en vigor para empresas con una facturación superior a ₹5 crore. Cada factura que entra en el ámbito debe compensarse a través de un Portal de Registro de Facturas gubernamental antes de ser legalmente válida.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'India');
UPDATE deep_dive_page_translations SET mandate_summary = 'Indiens GST-E-Invoicing-Mandat wurde durch schrittweise Absenkung der Umsatzschwelle eingeführt, statt durch einen einzigen Stichtag — es gilt inzwischen für Unternehmen mit einem Umsatz über ₹5 Crore. Jede betroffene Rechnung muss über ein staatliches Invoice Registration Portal freigegeben werden, bevor sie rechtsgültig ist.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'India');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat de facturation électronique GST de l''Inde a été déployé en abaissant progressivement le seuil de chiffre d''affaires plutôt que via une date unique — il s''applique désormais aux entreprises dont le chiffre d''affaires dépasse ₹5 crore. Chaque facture concernée doit être validée via un portail gouvernemental d''enregistrement des factures avant d''être juridiquement valide.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'India');
UPDATE deep_dive_page_translations SET mandate_summary = 'Italia aplica el mandato de compensación más maduro de todo este tracker — B2G desde 2014, y todas las transacciones domésticas B2B/B2C desde 2019, a través del Sistema di Interscambio. La actividad actual es mantenimiento rutinario del esquema (FatturaPA v1.9.1), no un nuevo requisito.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Italy');
UPDATE deep_dive_page_translations SET mandate_summary = 'Italien betreibt das ausgereifteste Clearing-Mandat in diesem gesamten Tracker — B2G seit 2014 und alle inländischen B2B-/B2C-Transaktionen seit 2019, über das Sistema di Interscambio. Die aktuelle Aktivität ist routinemäßige Schemapflege (FatturaPA v1.9.1), keine neue Anforderung.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Italy');
UPDATE deep_dive_page_translations SET mandate_summary = 'L''Italie applique le mandat de contrôle le plus mature de tout ce tracker — B2G depuis 2014, et toutes les transactions domestiques B2B/B2C depuis 2019, via le Sistema di Interscambio. L''activité actuelle est une maintenance de routine du schéma (FatturaPA v1.9.1), pas une nouvelle exigence.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Italy');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de compensación MyInvois de Malasia se está implementando de arriba hacia abajo según la facturación de la empresa, cubriendo ya en 2026 a las empresas del nivel RM1–5 millones. Cada nivel recibe un período de flexibilidad tras su fecha de inicio formal antes de que se endurezca la aplicación.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Malaysia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Malaysias MyInvois-Clearing-Mandat wird von oben nach unten nach Unternehmensumsatz eingeführt und deckt seit 2026 bereits Unternehmen der Stufe RM1–5 Mio. ab. Jede Stufe erhält nach ihrem formalen Starttermin eine Übergangsfrist, bevor die Durchsetzung strenger wird.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Malaysia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat de contrôle MyInvois de la Malaisie se déploie du haut vers le bas selon le chiffre d''affaires des entreprises, couvrant déjà en 2026 le palier RM1 à 5 millions. Chaque palier bénéficie d''une période de tolérance après sa date de début formelle avant un durcissement de l''application.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Malaysia');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de compensación CFDI de México tiene más de una década y está plenamente vigente para todas las empresas — la actividad actual son actualizaciones de versión (CFDI 4.0) y el mantenimiento anual de catálogos, no una nueva implementación. Una reforma fiscal de 2026 endurece los requisitos de autenticidad sobre el sistema ya existente.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Mexico');
UPDATE deep_dive_page_translations SET mandate_summary = 'Mexikos CFDI-Clearing-Mandat ist über ein Jahrzehnt alt und für alle Unternehmen vollständig in Kraft — die aktuelle Aktivität sind Versionsupgrades (CFDI 4.0) und die jährliche Katalogpflege, kein neuer Rollout. Eine Steuerreform 2026 verschärft die Echtheitsanforderungen auf dem bestehenden System.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Mexico');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat de contrôle CFDI du Mexique a plus d''une décennie et est pleinement en vigueur pour toutes les entreprises — l''activité actuelle concerne des mises à niveau de version (CFDI 4.0) et la maintenance annuelle des catalogues, pas un nouveau déploiement. Une réforme fiscale de 2026 renforce les exigences d''authenticité sur le système existant.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Mexico');
UPDATE deep_dive_page_translations SET mandate_summary = 'Nueva Zelanda utiliza el mismo marco Peppol que Australia, pero su mandato reside en las Normas de Contratación Pública, no en la legislación fiscal. Los organismos del gobierno central deben poder recibir facturas electrónicas desde marzo de 2022, y las obligaciones se amplían a los grandes proveedores que venden al gobierno a partir de 2027.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand');
UPDATE deep_dive_page_translations SET mandate_summary = 'Neuseeland nutzt denselben Peppol-Rahmen wie Australien, aber sein Mandat ist in den staatlichen Beschaffungsregeln verankert, nicht im Steuerrecht. Behörden der Zentralregierung müssen seit März 2022 E-Rechnungen empfangen können, wobei die Pflichten ab 2027 auf große Lieferanten an die Regierung ausgeweitet werden.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand');
UPDATE deep_dive_page_translations SET mandate_summary = 'La Nouvelle-Zélande utilise le même cadre Peppol que l''Australie, mais son mandat relève des règles de passation des marchés publics, et non du droit fiscal. Les agences du gouvernement central doivent pouvoir recevoir des factures électroniques depuis mars 2022, les obligations s''étendant aux grands fournisseurs vendant au gouvernement à partir de 2027.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de facturación electrónica B2B de Noruega solo se convirtió en ley efectiva en junio de 2026, tras años como propuesta — y es deliberadamente asimétrico: las empresas deben poder emitir facturas electrónicas desde 2027, tres años completos antes de que llegue el requisito de recepción en 2030.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Norway');
UPDATE deep_dive_page_translations SET mandate_summary = 'Norwegens B2B-E-Invoicing-Mandat wurde erst im Juni 2026 nach jahrelanger Vorlage tatsächlich Gesetz — und es ist bewusst asymmetrisch: Unternehmen müssen ab 2027 E-Rechnungen ausstellen können, ganze drei Jahre bevor die Empfangspflicht 2030 eintritt.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Norway');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat norvégien de facturation électronique B2B n''est devenu réellement loi qu''en juin 2026, après des années à l''état de proposition — et il est délibérément asymétrique : les entreprises doivent pouvoir émettre des factures électroniques dès 2027, trois années complètes avant l''arrivée de l''obligation de réception en 2030.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Norway');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de facturación electrónica (CPE) de Perú se aplica a todos los contribuyentes desde 2022, el punto final de una implementación que comenzó con los mayores contribuyentes en 2017. Cada factura debe ser validada directamente por SUNAT o por un OSE autorizado antes de tener validez legal.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Peru');
UPDATE deep_dive_page_translations SET mandate_summary = 'Perus E-Invoicing-Mandat (CPE) gilt seit 2022 für alle Steuerpflichtigen — der Endpunkt eines Rollouts, der 2017 mit den größten Steuerpflichtigen begann. Jede Rechnung muss entweder direkt von SUNAT oder von einem autorisierten OSE validiert werden, bevor sie Rechtsgültigkeit besitzt.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Peru');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat de facturation électronique (CPE) du Pérou s''applique à tous les contribuables depuis 2022, aboutissement d''un déploiement débuté avec les plus grands contribuables en 2017. Chaque facture doit être validée soit directement par la SUNAT, soit par un OSE agréé, avant d''avoir une valeur juridique.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Peru');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de compensación KSeF de Polonia ya está en vigor por etapas: para los grandes contribuyentes desde febrero de 2026, y para prácticamente todas las demás empresas registradas a efectos del IVA desde abril de 2026, tras una versión anterior del sistema que fue pausada y reconstruida después de una auditoría técnica. Los microempresarios y la aplicación de sanciones llegan en 2027.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Poland');
UPDATE deep_dive_page_translations SET mandate_summary = 'Polens KSeF-Clearing-Mandat ist bereits stufenweise in Kraft: für Großsteuerpflichtige seit Februar 2026 und für praktisch alle übrigen umsatzsteuerlich registrierten Unternehmen seit April 2026, nach einer früheren Version des Systems, die nach einer technischen Prüfung pausiert und neu aufgebaut wurde. Kleinstunternehmer und die Bußgeld-Durchsetzung folgen 2027.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Poland');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat de contrôle KSeF de la Pologne est déjà en vigueur par étapes : pour les grands contribuables depuis février 2026, et pour pratiquement toutes les autres entreprises immatriculées à la TVA depuis avril 2026, après qu''une version antérieure du système a été suspendue puis reconstruite à la suite d''un audit technique. Les micro-entrepreneurs et l''application des sanctions suivent en 2027.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Poland');
UPDATE deep_dive_page_translations SET mandate_summary = 'Portugal no tiene un mandato general de facturación electrónica B2B o B2C — algo genuinamente inusual entre los regímenes maduros de facturación electrónica de la UE — pero una densa capa de requisitos de software certificado y seguridad documental se aplica a todas las facturas de todos modos. Sí existe un verdadero mandato de formato estructurado para el B2G, que actualmente se está ampliando a las pequeñas y microempresas.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Portugal');
UPDATE deep_dive_page_translations SET mandate_summary = 'Portugal hat kein allgemeines B2B- oder B2C-E-Invoicing-Mandat — unter den ausgereiften E-Invoicing-Regimen der EU wirklich ungewöhnlich —, doch eine dichte Schicht aus Anforderungen an zertifizierte Software und Dokumentensicherheit gilt trotzdem für jede Rechnung. Ein echtes Mandat für ein strukturiertes Format besteht für B2G und wird derzeit auf kleine und Kleinstunternehmen ausgeweitet.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Portugal');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le Portugal n''a pas de mandat général de facturation électronique B2B ou B2C — chose réellement inhabituelle parmi les régimes matures de facturation électronique de l''UE — mais une couche dense d''exigences en matière de logiciels certifiés et de sécurité documentaire s''applique néanmoins à chaque facture. Un véritable mandat de format structuré existe pour le B2G, actuellement étendu aux petites et micro-entreprises.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Portugal');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de compensación RO e-Factura de Rumanía está plenamente vigente para las transacciones B2B y B2G desde mediados de 2024, tras comenzar como canal voluntario en 2021 y volverse obligatorio para B2G en 2022. El reporte B2C se incorporó en 2025, y la aplicación plena alcanza a los pequeños contribuyentes a mediados de 2026.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Romania');
UPDATE deep_dive_page_translations SET mandate_summary = 'Rumäniens RO-e-Factura-Clearing-Mandat ist seit Mitte 2024 vollständig für B2B- und B2G-Transaktionen in Kraft, nachdem es 2021 als freiwilliger Kanal begann und 2022 für B2G verpflichtend wurde. Die B2C-Meldung kam 2025 hinzu, die vollständige Durchsetzung erreicht Kleinunternehmer Mitte 2026.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Romania');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat de contrôle RO e-Factura de la Roumanie est pleinement en vigueur pour les transactions B2B et B2G depuis mi-2024, après avoir débuté comme canal volontaire en 2021 puis être devenu obligatoire pour le B2G en 2022. La déclaration B2C a rejoint le dispositif en 2025, et l''application complète atteint les petits contribuables mi-2026.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Romania');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato ZATCA de Arabia Saudí está plenamente en vigor y avanza hacia una cobertura universal: toda empresa registrada a efectos del IVA ha tenido que generar facturas electrónicas desde diciembre de 2021, y la integración directa con el gobierno se está extendiendo ahora a través de olas de facturación cada vez menores, alcanzando a las empresas con más de SAR 375.000 a mediados de 2026.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Saudi-Arabiens ZATCA-Mandat ist vollständig in Kraft und bewegt sich auf eine flächendeckende Abdeckung zu: Jedes umsatzsteuerlich registrierte Unternehmen musste seit Dezember 2021 E-Rechnungen erstellen, und die direkte Integration mit der Regierung wird nun schrittweise über immer kleinere Umsatzwellen ausgeweitet und erreicht bis Mitte 2026 Unternehmen mit einem Umsatz über SAR 375.000.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat ZATCA de l''Arabie saoudite est pleinement en vigueur et s''oriente vers une couverture universelle : toute entreprise immatriculée à la TVA a dû générer des factures électroniques depuis décembre 2021, et l''intégration directe avec le gouvernement s''étend désormais par vagues de chiffre d''affaires décroissantes, atteignant les entreprises au-delà de 375 000 SAR d''ici mi-2026.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia');
UPDATE deep_dive_page_translations SET mandate_summary = 'InvoiceNow de Singapur comenzó en 2019 como una red de intercambio Peppol puramente voluntaria, y ahora está transitando hacia un verdadero requisito de reporte fiscal — GST InvoiceNow ya es obligatorio para los nuevos registrantes voluntarios de GST, con una implementación por fases para las empresas ya registradas a efectos del GST que se extiende hasta 2031, uno de los plazos más largos de este tracker.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Singapore');
UPDATE deep_dive_page_translations SET mandate_summary = 'Singapurs InvoiceNow begann 2019 als rein freiwilliges Peppol-Austauschnetzwerk und befindet sich nun im Übergang zu einer echten Steuermeldepflicht — GST InvoiceNow ist bereits für neue freiwillige GST-Registrierte verpflichtend, wobei sich die Einführung für bereits GST-registrierte Unternehmen bis 2031 erstreckt, einer der längsten Vorlaufzeiten in diesem Tracker.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Singapore');
UPDATE deep_dive_page_translations SET mandate_summary = 'InvoiceNow, à Singapour, a débuté en 2019 comme un réseau d''échange Peppol purement volontaire, et effectue désormais la transition vers une véritable obligation de déclaration fiscale — GST InvoiceNow est déjà obligatoire pour les nouveaux inscrits volontaires à la GST, le déploiement pour les entreprises déjà immatriculées à la GST s''étalant jusqu''en 2031, l''un des délais les plus longs de ce tracker.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Singapore');
UPDATE deep_dive_page_translations SET mandate_summary = 'El mandato de facturación electrónica B2B de Eslovaquia es ley con una fecha de inicio firme en 2027, después de que un plan voluntario anterior fuera aparcado discretamente en 2024. La facturación electrónica B2G/G2G ya es obligatoria desde 2023, y una vez que llegue el B2B, la transmisión deberá pasar por un "Cartero Digital" certificado que reporta los datos a la autoridad fiscal en el mismo paso.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Die Slowakei hat ein gesetzlich verankertes B2B-E-Invoicing-Mandat mit festem Starttermin 2027, nachdem ein früherer freiwilliger Plan 2024 still zurückgezogen wurde. B2G/G2G-E-Invoicing ist bereits seit 2023 verpflichtend, und sobald B2B eintrifft, muss die Übertragung über einen zertifizierten "Digitalen Postboten" laufen, der die Daten im selben Schritt an die Steuerbehörde meldet.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le mandat slovaque de facturation électronique B2B est une loi avec une date de début ferme en 2027, après qu''un plan volontaire antérieur a été discrètement abandonné en 2024. La facturation électronique B2G/G2G est déjà obligatoire depuis 2023, et une fois le B2B en place, la transmission devra passer par un « facteur numérique » certifié qui déclare les données à l''administration fiscale dans la même étape.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Slovakia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Los EAU construyeron su marco de facturación electrónica de forma inusualmente metódica — legislación, luego acreditación de proveedores de servicios, luego un piloto voluntario genuinamente libre de riesgo — todo antes de que comience el propio mandato. La primera entrada en vigor obligatoria es el 1 de enero de 2027 para las grandes empresas (ingresos de AED 50 millones o más), ampliándose a todas las demás empresas registradas a efectos del IVA seis meses después.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'United Arab Emirates');
UPDATE deep_dive_page_translations SET mandate_summary = 'Die VAE haben ihren E-Invoicing-Rahmen ungewöhnlich methodisch aufgebaut — Gesetzgebung, dann Akkreditierung von Dienstanbietern, dann ein wirklich risikofreies freiwilliges Pilotprojekt — alles noch vor Beginn des eigentlichen Mandats. Der erste verpflichtende Start ist der 1. Januar 2027 für Großunternehmen (Umsatz ab AED 50 Millionen), ausgeweitet auf alle übrigen umsatzsteuerlich registrierten Unternehmen sechs Monate später.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'United Arab Emirates');
UPDATE deep_dive_page_translations SET mandate_summary = 'Les EAU ont construit leur cadre de facturation électronique de façon inhabituellement méthodique — législation, puis accréditation des prestataires de services, puis un pilote volontaire véritablement sans risque — le tout avant même le début du mandat lui-même. La première entrée en vigueur obligatoire est le 1er janvier 2027 pour les grandes entreprises (chiffre d''affaires à partir de 50 millions d''AED), s''étendant à toutes les autres entreprises immatriculées à la TVA six mois plus tard.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'United Arab Emirates');
